      }));
    });

    const maxCases = Math.max(...smoothed.map(d => d.avgCases));
    const maxDays = Math.max(...years.map(y => yearData[y].length));

    const container = document.getElementById('final-chart');
    const W = container.clientWidth;
    const H = container.clientHeight;

    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0xfafaf8);
    scene.fog = new THREE.FogExp2(0xfafaf8, 0.008);

    const camera = new THREE.PerspectiveCamera(45, W / H, 0.1, 500);
    camera.position.set(55, 40, 55);
    camera.lookAt(0, 5, 0);

    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(W, H);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    container.appendChild(renderer.domElement);

    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;
    controls.dampingFactor = 0.05;
    controls.minDistance = 20;
    controls.maxDistance = 120;
    controls.maxPolarAngle = Math.PI / 2.1;
    controls.target.set(0, 5, 0);

    const ambient = new THREE.AmbientLight(0xffffff, 0.5);
    scene.add(ambient);

    const dirLight = new THREE.DirectionalLight(0xffffff, 0.8);
    dirLight.position.set(30, 50, 20);
    dirLight.castShadow = true;
    dirLight.shadow.mapSize.width = 1024;
    dirLight.shadow.mapSize.height = 1024;
    scene.add(dirLight);

    const fillLight = new THREE.DirectionalLight(0x8899bb, 0.3);
    fillLight.position.set(-20, 30, -10);
    scene.add(fillLight);

    function cfrColor(cases, deaths) {
      if (cases < 100) return new THREE.Color(0x2b6ca3);
      const cfr = Math.min(deaths / cases, 0.06);
      const t = cfr / 0.06;
      if (t < 0.33) return new THREE.Color(0x2b6ca3).lerp(new THREE.Color(0xe8d44d), t / 0.33);
      if (t < 0.66) return new THREE.Color(0xe8d44d).lerp(new THREE.Color(0xc23728), (t - 0.33) / 0.33);
      return new THREE.Color(0xc23728).lerp(new THREE.Color(0x5a0d14), (t - 0.66) / 0.34);
    }

    const terrainW = 60;
    const terrainD = 30;
    const heightScale = 30;
    const yearSpacing = terrainD / (years.length - 1);

    years.forEach((year, yi) => {
      const yd = yearData[year];
      if (yd.length < 2) return;

      const ribbonWidth = 3.5;
      const zCenter = -terrainD / 2 + yi * yearSpacing;

      const positions = [];
      const colors = [];
      const indices = [];

      yd.forEach((d, i) => {
        const xPos = -terrainW / 2 + (i / (maxDays - 1)) * terrainW;
        const h = Math.sqrt(d.avgCases / maxCases) * heightScale;
        const col = cfrColor(d.avgCases, d.avgDeaths);

        positions.push(xPos, 0, zCenter + ribbonWidth / 2);
        colors.push(col.r * 0.4, col.g * 0.4, col.b * 0.4);

        positions.push(xPos, h, zCenter);
        colors.push(col.r, col.g, col.b);

        positions.push(xPos, 0, zCenter - ribbonWidth / 2);
        colors.push(col.r * 0.4, col.g * 0.4, col.b * 0.4);

        if (i < yd.length - 1) {
          const b = i * 3;
          indices.push(b, b + 3, b + 1);
          indices.push(b + 3, b + 4, b + 1);
          indices.push(b + 1, b + 4, b + 2);
          indices.push(b + 4, b + 5, b + 2);
        }
      });

      const geom = new THREE.BufferGeometry();
      geom.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
      geom.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3));
      geom.setIndex(indices);
      geom.computeVertexNormals();

      const mat = new THREE.MeshLambertMaterial({
        vertexColors: true,
        side: THREE.DoubleSide,
        transparent: true,
        opacity: 0.92
      });

      const mesh = new THREE.Mesh(geom, mat);
      mesh.castShadow = true;
      mesh.receiveShadow = true;
      scene.add(mesh);

      const ridgePoints = yd.map((d, i) => {
        const xPos = -terrainW / 2 + (i / (maxDays - 1)) * terrainW;
        const h = Math.sqrt(d.avgCases / maxCases) * heightScale;
        return new THREE.Vector3(xPos, h + 0.05, zCenter);
      });
      const ridgeCurve = new THREE.BufferGeometry().setFromPoints(ridgePoints);
      const ridgeMat = new THREE.LineBasicMaterial({ color: 0x1a1a1a, linewidth: 1 });
      scene.add(new THREE.Line(ridgeCurve, ridgeMat));
    });

    const groundGeom = new THREE.PlaneGeometry(terrainW + 20, terrainD + 20);
    const groundMat = new THREE.MeshLambertMaterial({ color: 0xf0ede8, side: THREE.DoubleSide });
    const ground = new THREE.Mesh(groundGeom, groundMat);
    ground.rotation.x = -Math.PI / 2;
    ground.position.y = -0.1;
    ground.receiveShadow = true;
    scene.add(ground);

    const gridMat = new THREE.LineBasicMaterial({ color: 0xd0cdc8, transparent: true, opacity: 0.5 });

    const months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
    months.forEach((m, mi) => {
      const dayApprox = mi * 30.4;
      const xPos = -terrainW / 2 + (dayApprox / (maxDays - 1)) * terrainW;
      if (xPos > terrainW / 2) return;
      const pts = [
        new THREE.Vector3(xPos, 0, -terrainD / 2 - 2),
        new THREE.Vector3(xPos, 0, terrainD / 2 + 2)
      ];
      scene.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), gridMat));
    });

    const labelContainer = document.createElement('div');
    labelContainer.style.cssText = 'position:absolute;top:0;left:0;width:100%;height:100%;pointer-events:none;overflow:hidden;';
    container.appendChild(labelContainer);

    const labels = [];

    function addLabel(text, pos3d, style) {
      const el = document.createElement('div');
      el.textContent = text;
      el.style.cssText = 'position:absolute;font-family:JetBrains Mono,monospace;white-space:nowrap;' + (style || 'font-size:11px;color:#6b6b6b;');
      labelContainer.appendChild(el);
      labels.push({ el, pos: pos3d });
    }

    years.forEach((year, yi) => {
      const zCenter = -terrainD / 2 + yi * yearSpacing;
      addLabel(String(year), new THREE.Vector3(terrainW / 2 + 4, 0, zCenter), 'font-size:14px;color:#1a1a1a;font-weight:600;');
    });

    months.forEach((m, mi) => {
      const dayApprox = mi * 30.4;
      const xPos = -terrainW / 2 + (dayApprox / (maxDays - 1)) * terrainW;
      if (xPos > terrainW / 2) return;
      addLabel(m, new THREE.Vector3(xPos, 0, terrainD / 2 + 4), 'font-size:9px;color:#999;');
    });

    [100000, 500000, 1000000].forEach(val => {
      const h = Math.sqrt(val / maxCases) * heightScale;
      const label = val >= 1e6 ? (val / 1e6) + 'M' : (val / 1e3) + 'K';
      addLabel(label, new THREE.Vector3(-terrainW / 2 - 4, h, terrainD / 2 + 2), 'font-size:9px;color:#aaa;');
    });

    const waveAnnotations = [
      { label: 'First wave', dayApprox: 85, year: 2020 },
      { label: 'Winter surge', dayApprox: 340, year: 2020 },
      { label: 'Delta', dayApprox: 230, year: 2021 },
      { label: 'Omicron peak', dayApprox: 10, year: 2022 },
    ];

    waveAnnotations.forEach(a => {
      const yi = years.indexOf(a.year);
      const zCenter = -terrainD / 2 + yi * yearSpacing;
      const xPos = -terrainW / 2 + (a.dayApprox / (maxDays - 1)) * terrainW;
      const yd = yearData[a.year];
      const nearest = yd.reduce((best, d) => Math.abs(d.dayIndex - a.dayApprox) < Math.abs(best.dayIndex - a.dayApprox) ? d : best);
      const h = Math.sqrt(nearest.avgCases / maxCases) * heightScale;

      const markerPts = [
        new THREE.Vector3(xPos, h, zCenter),
        new THREE.Vector3(xPos, h + 5, zCenter)
      ];
      const markerMat = new THREE.LineBasicMaterial({ color: 0xc23728 });
      scene.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(markerPts), markerMat));

      const dotGeom = new THREE.SphereGeometry(0.4, 8, 8);
      const dotMat = new THREE.MeshBasicMaterial({ color: 0xc23728 });
      const dot = new THREE.Mesh(dotGeom, dotMat);
      dot.position.set(xPos, h, zCenter);
      scene.add(dot);

      addLabel(a.label, new THREE.Vector3(xPos, h + 6, zCenter), 'font-size:10px;color:#c23728;font-weight:600;');
    });

    function updateLabels() {
      const halfW = W / 2;
      const halfH = H / 2;
      labels.forEach(({ el, pos }) => {
        const projected = pos.clone().project(camera);
        const px = (projected.x * halfW) + halfW;
        const py = -(projected.y * halfH) + halfH;
        if (projected.z > 1) {
          el.style.display = 'none';
        } else {
          el.style.display = '';
          el.style.left = px + 'px';
          el.style.top = py + 'px';
          el.style.transform = 'translate(-50%, -50%)';
        }
      });
    }

    function animate() {
      requestAnimationFrame(animate);
      controls.update();
      updateLabels();
      renderer.render(scene, camera);
    }
    animate();

    window.addEventListener('resize', () => {
      const newW = container.clientWidth;
      const newH = container.clientHeight;
      camera.aspect = newW / newH;
      camera.updateProjectionMatrix();
      renderer.setSize(newW, newH);
    });
  });
</script>

<svelte:head>
  <title>A3 &middot; Visualization Design: COVID-19 in the United States</title>
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link href="https://fonts.googleapis.com/css2?family=Source+Serif+4:ital,opsz,wght@0,8..60,300;0,8..60,400;0,8..60,600;1,8..60,300;1,8..60,400&family=JetBrains+Mono:wght@300;400;600&display=swap" rel="stylesheet" />
</svelte:head>

<div class="page">

  <div class="masthead">
    <div class="masthead-kicker">A3 &middot; Visualization Design</div>
    <h1>Redesigning the COVID-19 Spiral<br/></h1>
    <div class="masthead-meta">
      <span><span class="dot"></span>Dataset: Google COVID-19 Open Data (US)</span>
      <span><span class="dot"></span>Jan 2020 &ndash; Sep 2022</span>
      <span><span class="dot"></span>978 daily records</span>
      <span><span class="dot"></span>Analysis: February 2026</span>
    </div>
  </div>

  <h2>Step 1 &middot; Reading the Visualization</h2>

  <p>The original visualization, published by the <em>New York Times</em>, uses a spiral form to display daily new COVID-19 cases in the United States from early 2020 through January 2022. Each revolution of the spiral represents one calendar year, with months marked along radial axes. The radial distance from the center encodes the volume of new daily cases, and a pink band represents a range which is likely the raw daily counts.</p>

  <img class="orig-viz" src="{base}/A3/nyt.png" alt="NYT spiral visualization of COVID-19 cases" />

  <h3>Key Insights from the Data</h3>
  <ul>
    <li><strong>Omicron dwarfed all previous waves:</strong> The January 2022 peak (the outermost spike near the top of the spiral) reached over 1.4 million daily new cases at its apex, roughly 5&times; larger than any prior wave. This is the most visually dramatic feature of the spiral.</li>
    <li><strong>Winter surges are a recurring pattern:</strong> Each year shows a pronounced case spike in the December&ndash;January period: the winter 2020&ndash;21 wave (~300K daily cases), the Delta-driven late 2021 surge, and the historic Omicron wave of January 2022. The seasonal pattern is one thing the spiral form communicates well.</li>
    <li><strong>The summer 2021 Delta wave:</strong> A visible bulge near the July mark of the 2021 ring shows the Delta variant surge, which peaked around 150&ndash;200K daily cases which is significant but modest compared to the winter waves.</li>
  </ul>

  <h2>Step 2 &middot; Critique of the Original Design</h2>

  <p>The spiral visualization is visually striking and succeeds as an attention-grabbing editorial piece. The choice to wrap time in a spiral rather than a line makes seasonal comparison intuitive: you can see at a glance that winter months consistently produce surges. The dramatic outward spike of the Omicron wave in January 2022 creates a powerful visual metaphor for how the variant "broke the pattern" of prior waves, and the gradual widening of each annual ring communicates escalation without needing to read any numbers. The labeling is minimal but functional, and the visual hierarchy (bold title, subtle month labels, year annotations along the spiral) guides the reader's eye from the outside in.</p>

  <p>However, the spiral form introduces several readability challenges. First, radial distance is one of the least accurate visual encodings for quantitative comparison. It is very difficult to judge whether the summer 2021 Delta wave was 60% or 80% as large as the winter 2020&ndash;21 surge. Second, the wide pink band adds visual noise without a clear legend explaining what it encodes. Third, the scale reference is disconnected from the data and easy to overlook, making it hard to attach concrete numbers to the visual. Finally, the reading order is unintuitive: does one start at the center (chronological beginning) or the outside (the most dramatic feature)? I noticed the Omicron spike first but then had to mentally rewind to the center to reconstruct the chronological narrative, creating cognitive friction. A linear time axis would resolve most of these issues at the cost of sacrificing the spiral's seasonal-comparison affordance and editorial punch.</p>

  <h2>Step 3 &middot; Sketches</h2>

  <div class="sketch-grid">

    <div class="sketch-card">
      <div class="sketch-label">Sketch 1</div>
      <img class="sketch1" src="{base}/A3/sketch1.png" alt="Sketch 1" />
      <h3>Rationale</h3>
      <ul>
        <li><strong>Motivation:</strong> I wanted to use a standard line chart with a linear time axis to address the readability issues of the spiral.</li>
        <li><strong>Intended message:</strong> I wanted to communicate the cyclical, year-over-year nature of pandemic waves and the dramatic Omicron wave in January 2022.</li>
        <li><strong>What worked:</strong> The linear time axis is easy to read and understand.</li>
        <li><strong>What didn't:</strong> The spiral is more visually striking and engaging than the line chart.</li>
        <li><strong>Next exploration:</strong> I would like to explore a faceted area chart to compare the different waves year by year.</li>
      </ul>
    </div>

    <div class="sketch-card">
      <div class="sketch-label">Sketch 2</div>
      <img class="sketch2" src="{base}/A3/sketch2.png" alt="Sketch 2" />
      <h3>Rationale</h3>
      <ul>
        <li><strong>Motivation:</strong> I wanted to use a faceted area chart to compare the different waves year by year.</li>
        <li><strong>Intended message:</strong> I wanted to communicate the cyclical, year-over-year nature of pandemic waves and the dramatic Omicron wave in January 2022.</li>
        <li><strong>What worked:</strong> The faceted area chart is easy to read and understand.</li>
        <li><strong>What didn't:</strong> The spiral is more visually striking and engaging than the faceted area chart.</li>
        <li><strong>Next exploration:</strong> I would like to explore a nonlinear chart type to match the engagement of the spiral.</li>
      </ul>
    </div>

    <div class="sketch-card">
      <div class="sketch-label">Sketch 3</div>
      <img class="sketch3" src="{base}/A3/sketch3.png" alt="Sketch 3" />
      <h3>Rationale</h3>
      <ul>
        <li><strong>Motivation:</strong> I wanted to use a non chronological approach to show how the COVID cases grew year after year. </li>
        <li><strong>Intended message:</strong> I wanted to communicate how the number of cases grew with each passing year. </li>
        <li><strong>What worked:</strong> The circles are visually effective in how they demonstrate the total amount of cases being the area. </li>
        <li><strong>What didn't:</strong> Hard to draw these circles whose area represents a numerical value accurately. Also hard to label the circles. </li>
        <li><strong>Next exploration:</strong> I'd like to put all these together to form a overall appealing graph without sacrificing numerical accuracy while maintaining visual appeal. </li>
      </ul>
    </div>

  </div>

  <h2>Step 4 &middot; Final Visualization</h2>

  <div class="chart-container" style="padding:0;overflow:hidden;position:relative;">
    <div id="final-chart" style="width:100%;height:600px;"></div>
    <div id="chart-overlay" style="position:absolute;top:16px;left:20px;pointer-events:none;">
      <div style="font-family:var(--serif);font-size:20px;font-weight:600;color:#1a1a1a;">The Pandemic Landscape</div>
      <div style="font-family:var(--serif);font-size:12px;color:#6b6b6b;margin-top:2px;">Daily new COVID-19 cases, U.S. &mdash; terrain height = 7-day avg, color = case fatality rate</div>
    </div>
    <div id="chart-legend" style="position:absolute;bottom:16px;left:20px;pointer-events:none;font-family:var(--mono);font-size:10px;color:#888;">
      <div style="display:flex;align-items:center;gap:6px;margin-bottom:4px;">
        <span style="display:inline-block;width:60px;height:10px;border-radius:3px;background:linear-gradient(to right,#2b6ca3,#e8d44d,#c23728,#5a0d14);"></span>
        <span>Low CFR &rarr; High CFR</span>
      </div>
      <div>Drag to orbit &middot; Scroll to zoom &middot; Source: Google COVID-19 Open Data</div>
    </div>
  </div>

  <h2>Step 5 &middot; Design Rationale &amp; Reflection</h2>

  <p>My final visualization uses a 3D terrain metaphor to communicate two central messages: (1) the sheer scale difference between the Omicron wave and all prior surges, and (2) the divergence between case volume and lethality over the course of the pandemic. Each of the three years (2020, 2021, 2022) is rendered as a separate ribbon of terrain arranged along the depth (Z) axis, with time-of-year running left to right (X axis) and case volume mapped to vertical height (Y axis). I applied a square-root scale to the height encoding so that the enormous Omicron peak does not flatten the earlier waves into invisibility, while still preserving a clear sense of magnitude difference. The second encoding layer is color: each point on the terrain surface is colored by the case fatality rate (deaths &divide; cases), using a blue-to-yellow-to-red gradient. This dual encoding allows the viewer to immediately see that early 2020, though modest in case volume, was the deadliest period per infection, while the towering Omicron ridge is predominantly blue, reflecting its far lower fatality rate. I chose a 7-day rolling average as a data transformation to smooth out the severe day-of-week reporting artifacts (weekends consistently underreported). The interactive orbit controls let the viewer rotate and zoom to compare years from different angles, partially compensating for the occlusion inherent in any 3D representation. However, the 3D perspective does obscure precise quantitative comparison and the back ribbons (2020) can be partially hidden behind the front ones depending on the viewing angle. Additionally, the choice to separate years into discrete ribbons rather than a continuous surface means the late-December-to-January transition between years (where the winter 2020&ndash;21 surge and the Omicron onset both occurred) is visually split across two ribbons.</p>

  <p>Reflecting on the critiques I raised in Step 2, the 3D terrain design directly addresses several of them while failing to resolve others. My primary critique of the NYT spiral was that radial distance is a poor encoding for quantitative comparison. The terrain's vertical height channel is more perceptually accurate, especially with the sqrt scale preserving visibility of smaller waves. The spiral's lack of a clear scale reference is addressed here through labeled height markers and the interactive ability to zoom in on specific regions. The spiral's ambiguous reading order (center-out vs. outside-in) is replaced by a natural left-to-right, front-to-back arrangement that follows both chronological time and calendar alignment simultaneously. However, the process of critique-by-redesign revealed a fundamental tension I had not anticipated: the spiral's greatest strength &mdash; its ability to overlay years concentrically for direct seasonal comparison &mdash; is actually difficult to replicate in any alternative layout. I also discovered that my critique of the spiral's "visual noise" from the pink band was somewhat unfair; when I attempted to encode a second variable (fatality rate via color), I introduced my own form of visual complexity that demands explanation. Ultimately, this redesign process taught me that the spiral was a more carefully considered design than my initial critique suggested: its weaknesses in precision were deliberate tradeoffs for editorial impact and seasonal-comparison affordance, and any alternative that tries to improve on one axis inevitably sacrifices something on another.</p>

  <footer>
    Dataset: Google COVID-19 Open Data (US)<br/>
    Original visualization: <em>New York Times</em> spiral chart of U.S. COVID-19 cases<br/>
    Analysis conducted February 2026
  </footer>

</div>

